ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (
     (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+shadows/i)
  OR (ImageFileName=/\\wmic\.exe$/i AND CommandLine=/shadowcopy\s+delete/i)
  OR (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)/i)
  OR (ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/delete\s+(catalog|systemstatebackup)/i)
  OR (ImageFileName=/\\(powershell|pwsh)\.exe$/i AND CommandLine=/Win32_Shadowcopy.{0,40}Delete/i)
  OR (ImageFileName=/\\net\.exe$/i AND CommandLine=/stop\s+.{0,30}(sql|backup|veeam|memtas|sophos|msexchange)/i)
  )
| case {
    ImageFileName=/\\vssadmin\.exe$/i | RecoveryAction := "vssadmin";
    ImageFileName=/\\wmic\.exe$/i | RecoveryAction := "wmic-shadow";
    ImageFileName=/\\bcdedit\.exe$/i | RecoveryAction := "bcdedit";
    ImageFileName=/\\wbadmin\.exe$/i | RecoveryAction := "wbadmin";
    ImageFileName=/\\(powershell|pwsh)\.exe$/i | RecoveryAction := "ps-shadow";
    ImageFileName=/\\net\.exe$/i | RecoveryAction := "net-stop";
    *
  }
| groupBy([aid, ComputerName, UserName], function=[count(field=RecoveryAction, distinct=true, as=distinct_actions), collect([RecoveryAction, CommandLine, ParentBaseFileName]), min(@timestamp, as=firstSeen), max(@timestamp, as=lastSeen)])
| distinct_actions >= 2
